import 'dart:convert'; import 'package:flutter_cache_manager/flutter_cache_manager.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'audio_quran_service.dart'; import 'quran_service.dart'; import 'reciter_service.dart';
class DownloadedSurah { final int surahNumber; final String surahName; final int reciterId; final String reciterName; const DownloadedSurah({required this.surahNumber, required this.surahName, required this.reciterId, required this.reciterName}); String get key=>'$reciterId:$surahNumber'; Map<String,dynamic> toJson()=>{'surahNumber':surahNumber,'surahName':surahName,'reciterId':reciterId,'reciterName':reciterName}; factory DownloadedSurah.fromJson(Map<String,dynamic> j)=>DownloadedSurah(surahNumber:j['surahNumber'],surahName:j['surahName'],reciterId:j['reciterId'],reciterName:j['reciterName']); }
class AudioDownloadService { static const _key='downloaded_surahs'; final AudioQuranService audioService; AudioDownloadService(this.audioService); static Future<List<DownloadedSurah>> loadDownloads() async { final p=await SharedPreferences.getInstance(); return (p.getStringList(_key)??[]).map((e)=>DownloadedSurah.fromJson(json.decode(e))).toList(); } static Future<void> _saveDownloads(List<DownloadedSurah> items) async { final p=await SharedPreferences.getInstance(); await p.setStringList(_key, items.map((e)=>json.encode(e.toJson())).toList()); } Future<void> downloadSurah({required Surah surah, required void Function(int,int) onProgress}) async { final rid=await ReciterService.getSelectedReciterId(); final rec=ReciterService.getReciterById(rid); int done=0; for(final a in surah.ayahs){ final url=await audioService.getAyahAudioUrl(surahNumber:surah.number, ayahNumber:a.number, recitationId:rid); await DefaultCacheManager().downloadFile(url); done++; onProgress(done, surah.ayahs.length); } final d=await loadDownloads(); final item=DownloadedSurah(surahNumber:surah.number,surahName:surah.name,reciterId:rid,reciterName:rec.name); d.removeWhere((x)=>x.key==item.key); d.add(item); await _saveDownloads(d); } Future<void> deleteSurahDownload({required Surah surah}) async { final rid=await ReciterService.getSelectedReciterId(); for(final a in surah.ayahs){ try{ final url=await audioService.getAyahAudioUrl(surahNumber:surah.number, ayahNumber:a.number, recitationId:rid); await DefaultCacheManager().removeFile(url);}catch(_){}} final d=await loadDownloads(); d.removeWhere((x)=>x.reciterId==rid && x.surahNumber==surah.number); await _saveDownloads(d); } }
